export GH_CONFIG_DIR=$HOME/.config/gh-rowan; t0=$(date +%s); left="$@"
[ -f /tmp/enqueue-hold ] && { echo "HOLD $(cat /tmp/enqueue-hold)"; exit 0; }
# green = the latest ci.yml run on the PR's head branch concluded success; pending = in progress/queued; red = failure on the head run
SKIP=""; [ -f /tmp/enqueue-skip ] && SKIP=$(grep -oE "[0-9]+" /tmp/enqueue-skip | tr "\n" " "); for sk in ${SKIP:-}; do left=$(echo " $left " | sed "s/ $sk / /g"); done
while [ -n "$left" ] && [ $(( $(date +%s)-t0 )) -lt 1500 ]; do next=""; for p in $left; do br=$(gh pr view $p -R mas-bandwidth/nova-tools --json headRefName -q .headRefName 2>/dev/null); st=$(gh run list -R mas-bandwidth/nova-tools --branch "$br" --workflow ci.yml --limit 1 --json status,conclusion -q '.[0] | "\(.status) \(.conclusion)"' 2>/dev/null); case "$st" in "completed success") r=$(gh pr merge $p -R mas-bandwidth/nova-tools 2>&1 | tail -1 | cut -c1-80); echo "PR$p green -> queued ($r)";; "completed failure"|"completed cancelled") echo "PR$p RED/CANCELLED: $st";; *) next="$next $p";; esac; done; left=$next; [ -n "$left" ] && sleep 60; done; echo "done left=[$left]"
